scripts.preRequest:
var L = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
function rL() { return L[Math.floor(Math.random() * 26)]; }
function dig(nums, weights) {
  var sum = 0;
  for (var i = 0; i < weights.length; i++) sum += nums[i] * weights[i];
  var mod = sum % 11;
  return mod < 2 ? 0 : 11 - mod;
}
var n = [];
for (var i = 0; i < 9; i++) n.push(Math.floor(Math.random() * 10));
var d1 = dig(n, [10, 9, 8, 7, 6, 5, 4, 3, 2]);
var d2 = dig(n.concat([d1]), [11, 10, 9, 8, 7, 6, 5, 4, 3, 2]);
rq.environment.set("documentoCliente", n.join("") + String(d1) + String(d2));
rq.environment.set("placa", rL() + rL() + rL() + String(Math.floor(Math.random() * 10)) + rL() + String(Math.floor(Math.random() * 10)) + String(Math.floor(Math.random() * 10)));
var codN = String(Math.floor(Math.random() * 1000));
while (codN.length < 3) codN = "0" + codN;
rq.environment.set("codigoServico", rL() + rL() + rL() + "-" + codN);
rq.environment.set("codigoItem", rL() + rL() + rL() + "-" + codN);
rq.environment.set("runSuffix", String(Date.now()).slice(-6));

